const items = collections['c35ce8ea-60bf-44a5-96f1-88c7298ba891']?.data || [];
const likesData = collections['ac3fae73-14b0-4063-8109-fdf84162bd21']?.data || [];

// Создаем маппинг для лайков и дизлайков
const likesCountMap = {};
const dislikesCountMap = {};

likesData.forEach(item => {
    if (item?.type === 'like' && item?.tier_list_id) {
        likesCountMap[item.tier_list_id] = (likesCountMap[item.tier_list_id] || 0) + 1;
    }
    if (item?.type === 'dislike' && item?.tier_list_id) {
        dislikesCountMap[item.tier_list_id] = (dislikesCountMap[item.tier_list_id] || 0) + 1;
    }
});

// Добавляем количество лайков и дизлайков к каждому элементу и сортируем
const sortedItems = items
    .map(item => ({
        ...item,
        likes_count: likesCountMap[item.id] || 0,
        dislikes_count: dislikesCountMap[item.id] || 0,
        created_at: item?.created_at || item?.createdAt || null // пробуем разные варианты
    }))
    .sort((a, b) => {
        const aHasReactions = a.likes_count > 0 || a.dislikes_count > 0;
        const bHasReactions = b.likes_count > 0 || b.dislikes_count > 0;

        // Случай 1: У обоих есть реакции
        if (aHasReactions && bHasReactions) {
            const scoreA = a.likes_count - a.dislikes_count;
            const scoreB = b.likes_count - b.dislikes_count;
            return scoreB - scoreA;
        }

        // Случай 2: У a есть реакции, у b нет
        if (aHasReactions && !bHasReactions) {
            return -1; // a выше (b ниже)
        }

        // Случай 3: У b есть реакции, у a нет
        if (!aHasReactions && bHasReactions) {
            return 1; // a ниже (b выше)
        }

        // Случай 4: У обоих нет реакций - сортируем по created_at (новые выше)
        const dateA = new Date(a.created_at || 0);
        const dateB = new Date(b.created_at || 0);
        return dateB - dateA; // более новые даты больше → выше
    });

return sortedItems;

